  'public.terms': "Умови використання",
  'public.privacy': "Політика конфіденційності",
  'landing.login': "Увійти",
  'privacy.date': "Редакція від 30.10.2026",
  'privacy.contact': "Зв’язок з питань даних",
  'privacy.who.h': "Хто ми",
  'privacy.who.t': "LANKA — сервіс для стоматологічних клінік. Клініка, яка ним користується, є володільцем персональних даних своїх пацієнтів, а LANKA обробляє їх за її дорученням і лише для роботи сервісу.",
  'privacy.what.h': "Які дані обробляються",
  'privacy.what.t': "Дані про пацієнтів, записи й лікування, які клініка бере зі своєї системи (Cliniccards); дані співробітників (ім’я, пошта, роль, журнал дій); листування пацієнтів із клінікою в підключених каналах (Telegram, Instagram, Facebook Messenger, WhatsApp, Viber, чат на сайті) і пов’язані з ним службові ідентифікатори. Діагнози, медичні записи й файли пацієнтів не зчитуються.",
  'privacy.why.h': "Навіщо",
  'privacy.why.t': "Звіти для керівника, нагадування й відповіді пацієнтам від імені клініки, облік заявок на запис, статистика звернень. Ми не продаємо дані, не використовуємо їх для реклами та не навчаємо на них моделі.",
  'privacy.who2.h': "Кому передаються дані",
  'privacy.who2.t': "Лише постачальникам, без яких сервіс не працює: хостинг, пошта, платіжний сервіс, мессенджери, в яких клініка спілкується з пацієнтами, і постачальник ШІ (лише якщо клініка вмикає ШІ; імена й телефони пацієнтів до нього не передаються). Дані кожної клініки відокремлені від даних інших.",
  'privacy.meta.h': "Facebook, Instagram, Messenger і WhatsApp",
  'privacy.meta.t': "Клініка сама підключає свій акаунт і дозволяє доступ. Ми отримуємо лише повідомлення, адресовані клініці, і відповідаємо в межах правил платформи (протягом 24 годин після повідомлення людини). Токени доступу зберігаються зашифрованими. Якщо ви зняли доступ у Facebook чи Instagram, підключення та токени видаляються автоматично.",
  'privacy.store.h': "Зберігання",
  'privacy.store.t': "Дані зберігаються, поки діє договір із клінікою, у захищеній базі з розмежуванням за клініками. Після завершення договору їх видаляють на вимогу клініки.",
  'privacy.rights.h': "Ваші права",
  'privacy.rights.t': "Пацієнт звертається до клініки, яка є володільцем його даних: вона виправляє чи видаляє їх у своїй системі, а в LANKA вони оновлюються. Припинити повідомлення можна будь-коли командою «Зупинити».",
  'privacy.delete.h': "Видалення даних",
  'privacy.delete.t': "Запит на видалення даних, переданий через Facebook або Instagram, обробляється автоматично: видаляються підключені акаунти з токенами, листування й прив’язки чатів із вашим ідентифікатором. Ви отримуєте код підтвердження та сторінку, де видно результат.",
