  'dash.noData1': 'Дані клініки ще не завантажені. ',
  'dash.noData2': ', і звіти заповняться автоматично.',
  'dash.notLoaded1': 'Ключ збережено, але дані ще не завантажені. ',
  'audit.terms.accepted': 'Прийнято угоду про обробку даних',
  'audit.report.exported': 'Звіт завантажено у файл',
  'audit.clinic.work_hours': 'Змінено робочі години клініки',
  'audit.auth.password_reset': 'Пароль скинуто',
  'terms.title': 'Угода про обробку персональних даних',
  'terms.gateIntro': 'Щоб працювати далі, прийміть угоду від імені клініки. Її приймає власник.',
  'terms.acceptReg': 'Я приймаю угоду про обробку персональних даних від імені клініки.',
  'terms.readLink': 'Прочитати угоду',
  'terms.accept': 'Я приймаю цю угоду від імені клініки',
  'terms.acceptBtn': 'Прийняти',
  'terms.p1': 'Сторони. Ви дієте від імені клініки («Клініка») і приймаєте цю угоду з LANKA («Сервіс»). Ви підтверджуєте, що маєте повноваження це робити.',
  'terms.p2': 'Ролі. Клініка залишається володільцем персональних даних своїх пацієнтів. Сервіс обробляє їх лише за дорученням Клініки.',
  'terms.p3': "Що робить Сервіс. За API-ключем Клініки читає її дані з Cliniccards (лише читання: Сервіс нічого не змінює і не видаляє в Cliniccards), зберігає їх і показує співробітникам Клініки у звітах і списках завдань. Якщо Клініка це вмикає, Сервіс також надсилає пацієнтам повідомлення в месенджерах від імені Клініки (див. пункти 10 і 11).",
  'terms.p4': "Мета. Звіти та завдання адміністратора Клініки і, якщо Клініка це ввімкне, повідомлення пацієнтам та відповіді в чаті. Сервіс не продає дані і не використовує їх для реклами. Зовнішнім сервісам штучного інтелекту дані передаються лише так, як описано в пункті 11.",
  'terms.p5': 'Підстави. Клініка підтверджує, що має право обробляти ці дані, що пацієнти підписали її стандартну згоду на обробку персональних даних і що Cliniccards дозволяє підключати сторонні програми за API-ключем.',
  'terms.p6': 'Доступ. Дані бачать лише співробітники Клініки за своїми ролями: лікар не бачить фінансових даних пацієнтів. Дії співробітників записуються в історію.',
  'terms.p7': 'Захист. З’єднання захищене, ключ Cliniccards зберігається зашифрованим, вхід захищено паролем від 10 символів, обмеженням спроб і підтвердженням пошти.',
  'terms.p8': 'Видалення. Клініка може будь-коли вивантажити свої дані та повністю видалити їх із Сервісу в налаштуваннях. З робочої бази вони зникають одразу, у резервних копіях зберігаються до їх планової заміни.',
  'terms.p9': 'Інциденти. Якщо ми виявимо витік даних, повідомимо Клініку без невиправданої затримки.',
  'terms.p10': "Месенджери. Для зв’язку з пацієнтами Сервіс користується Telegram (бот Клініки): це підрядник, через якого проходять повідомлення. Сервіс пише лише тим, хто сам підключився до бота. Службові повідомлення (нагадування про запис) надсилаються за налаштуваннями Клініки, рекламні — лише пацієнтам, які дали згоду, і лише з підтвердженням співробітника, якщо Клініка не вирішила інакше. Пацієнт може відмовитися командою «Зупинити». Клініка відповідає за те, що має право писати своїм пацієнтам.",
  'terms.p11': "Штучний інтелект. Помічник на основі ШІ вимкнений, поки Клініка його не ввімкне. Якщо ввімкнено, текст повідомлень пацієнта в чаті з ботом і підсумкові відомості з бази Клініки (наприклад, скільки місяців минуло від останньої чистки, вільні вікна розкладу) передаються зовнішньому постачальнику ШІ лише для підготовки відповіді. Імена й телефони пацієнтів у запитах не передаються, але пацієнт може сам написати їх у повідомленні. ШІ не дає медичних порад: теми здоров’я, цін і скарг передаються співробітнику. Клініка може вимкнути помічника в будь-який момент. Постачальник ШІ є підрядником Сервісу. Те саме стосується ШІ-помічника керівника, якщо Клініка його вмикає: текст запитань співробітників до даних і підсумкові числа звітів без імен і телефонів пацієнтів передаються постачальнику ШІ.",
