  'public.terms': "Условия использования",
  'public.privacy': "Политика конфиденциальности",
  'landing.login': "Войти",
  'privacy.date': "Редакция от 30.10.2026",
  'privacy.contact': "Связь по вопросам данных",
  'privacy.who.h': "Кто мы",
  'privacy.who.t': "LANKA — сервис для стоматологических клиник. Клиника, которая им пользуется, является владельцем персональных данных своих пациентов, а LANKA обрабатывает их по её поручению и только для работы сервиса.",
  'privacy.what.h': "Какие данные обрабатываются",
  'privacy.what.t': "Данные о пациентах, записях и лечении, которые клиника берёт из своей системы (Cliniccards); данные сотрудников (имя, почта, роль, журнал действий); переписка пациентов с клиникой в подключённых каналах (Telegram, Instagram, Facebook Messenger, WhatsApp, Viber, чат на сайте) и связанные с ней служебные идентификаторы. Диагнозы, медицинские записи и файлы пациентов не считываются.",
  'privacy.why.h': "Зачем",
  'privacy.why.t': "Отчёты для руководителя, напоминания и ответы пациентам от имени клиники, учёт заявок на запись, статистика обращений. Мы не продаём данные, не используем их для рекламы и не обучаем на них модели.",
  'privacy.who2.h': "Кому передаются данные",
  'privacy.who2.t': "Только поставщикам, без которых сервис не работает: хостинг, почта, платёжный сервис, мессенджеры, в которых клиника общается с пациентами, и поставщик ИИ (только если клиника включает ИИ; имена и телефоны пациентов ему не передаются). Данные каждой клиники отделены от данных других.",
  'privacy.meta.h': "Facebook, Instagram, Messenger и WhatsApp",
  'privacy.meta.t': "Клиника сама подключает свой аккаунт и разрешает доступ. Мы получаем только сообщения, адресованные клинике, и отвечаем в рамках правил платформы (в течение 24 часов после сообщения человека). Токены доступа хранятся зашифрованными. Если вы сняли доступ в Facebook или Instagram, подключение и токены удаляются автоматически.",
  'privacy.store.h': "Хранение",
  'privacy.store.t': "Данные хранятся, пока действует договор с клиникой, в защищённой базе с разделением по клиникам. После завершения договора их удаляют по требованию клиники.",
  'privacy.rights.h': "Ваши права",
  'privacy.rights.t': "Пациент обращается в клинику, которая является владельцем его данных: она исправляет или удаляет их в своей системе, а в LANKA они обновляются. Прекратить сообщения можно в любой момент командой «Остановить».",
  'privacy.delete.h': "Удаление данных",
  'privacy.delete.t': "Запрос на удаление данных, переданный через Facebook или Instagram, обрабатывается автоматически: удаляются подключённые аккаунты с токенами, переписка и привязки чатов с вашим идентификатором. Вы получаете код подтверждения и страницу, где виден результат.",
  'deletion.title': "Удаление данных",
  'deletion.intro': "Здесь виден результат запроса на удаление данных, поданного через Facebook или Instagram.",
  'deletion.notFound': "Запрос с таким кодом не найден.",
  'deletion.noCode': "Код подтверждения не указан.",
  'deletion.code': "Код",
  'deletion.status': "Состояние",
  'deletion.done': "Данные удалены",
  'deletion.revoked': "Доступ отозван",
  'deletion.accounts': "Отключено подключений",
  'deletion.messages': "Удалено сообщений",
  'deletion.links': "Удалено привязок чатов",
  'deletion.requests': "Удалено заявок",
  'ld.title': "Заявки с сайта и рекламы",
  'ld.intro': "Форма на вашем сайте (или плагин форм, конструктор сайта, Zapier) отправляет заявку на этот адрес: она попадает в обращения, связывается с карточкой по телефону, а администратор получает уведомление. Метки рекламы (utm_source, utm_campaign) сохраняются и показывают, откуда пришёл человек.",
  'ld.origins': "Сайты, с которых форма отправляется из браузера (каждый с новой строки); плагинам на сервере это не нужно",
  'ld.url': "Адрес для формы (POST, JSON или обычная форма):",
  'ld.fields': "Поля: name, phone, message, utm_source, utm_medium, utm_campaign, page. Добавьте скрытое пустое поле website: роботы его заполняют, и заявка отбрасывается.",
  'ld.onDone': "Приём заявок включён.",
  'ld.offDone': "Приём заявок выключен.",
  'ld.rotateConfirm': "Создать новый адрес? Старый перестанет работать, формы на сайте нужно будет обновить.",
  'ld.rotated': "Новый адрес создан, обновите формы на сайте.",
  'ld.meta': "Заявки из рекламных форм Facebook и Instagram (Lead Ads) приходят автоматически через подключённую страницу Messenger: в приложении Meta нужно разрешение leads_retrieval и подписка страницы на leadgen.",
  'ml.title': "Facebook и Instagram: подключение одним входом",
  'ml.intro': "Владелец или управляющий входит в Facebook и в диалоге Meta выбирает страницу клиники и связанный аккаунт Instagram. Подключаются Messenger, Direct в Instagram и заявки из рекламных форм. Токены хранятся зашифрованными.",
  'ml.connect': "Подключить через Facebook",
  'ml.again': "Подключить заново",
