  'ml.expiring': "Доступ заканчивается. Подключите заново, чтобы сообщения не прекратились.",
  'ml.invalid': "Доступ отозван или перестал действовать: сообщения не приходят. Подключите заново.",
  'ml.rules': "Ответить можно только в течение 24 часов после сообщения человека. Доступ можно отозвать в настройках Facebook: подключение тогда исчезнет само.",
  'ml.err.fail': "Не удалось подключить Facebook. Попробуйте ещё раз.",
  'ml.err.denied': "Доступ к Facebook не предоставлен. Можно попробовать ещё раз.",
  'ml.err.taken': "Эта страница или аккаунт уже подключены к другой клинике.",
  'ml.err.plan': "Несколько каналов входят в тариф «Про».",
  'ml.err.demo': "В демо подключение недоступно.",
  'ml.err.off': "Подключение через Facebook ещё не настроено владельцем сервиса.",
  'ml.err.nopages': "В предоставленном доступе нет страницы Facebook: выберите страницу клиники в диалоге Facebook.",
  'ml.err.subscribe': "Facebook не разрешил подписаться на сообщения страницы: проверьте разрешения приложения.",
  'ml.doneIg': "Подключён Instagram. Messenger не подключён: в конфигурации нет разрешения на сообщения страницы.",
  'ml.err.noperm': "В предоставленном доступе нет разрешений на сообщения Instagram или Messenger. Подключите заново и оставьте разрешения в диалоге Facebook.",
  'plan.title': "Тариф и использование",
