  'dash.noData2': ', и отчёты заполнятся автоматически.',
  'dash.notLoaded1': 'Ключ сохранён, но данные ещё не загружены. ',
  'terms.title': 'Соглашение об обработке персональных данных',
  'terms.gateIntro': 'Чтобы работать дальше, примите соглашение от имени клиники. Его принимает владелец.',
  'terms.acceptReg': 'Я принимаю соглашение об обработке персональных данных от имени клиники.',
  'terms.readLink': 'Прочитать соглашение',
  'terms.accept': 'Я принимаю это соглашение от имени клиники',
  'terms.acceptBtn': 'Принять',
  'terms.p1': 'Стороны. Вы действуете от имени клиники («Клиника») и принимаете это соглашение с LANKA («Сервис»). Вы подтверждаете, что имеете полномочия это делать.',
  'terms.p2': 'Роли. Клиника остаётся владельцем персональных данных своих пациентов. Сервис обрабатывает их только по поручению Клиники.',
  'terms.p3': "Что делает Сервис. По API-ключу Клиники читает её данные из Cliniccards (только чтение: Сервис ничего не меняет и не удаляет в Cliniccards), хранит их и показывает сотрудникам Клиники в отчётах и списках задач. Если Клиника это включает, Сервис также отправляет пациентам сообщения в мессенджерах от имени Клиники (см. пункты 10 и 11).",
  'terms.p4': "Цель. Отчёты и задачи администратора Клиники и, если Клиника это включит, сообщения пациентам и ответы в чате. Сервис не продаёт данные и не использует их для рекламы. Внешним сервисам искусственного интеллекта данные передаются только так, как описано в пункте 11.",
  'terms.p5': 'Основания. Клиника подтверждает, что вправе обрабатывать эти данные, что пациенты подписали её стандартное согласие на обработку персональных данных и что Cliniccards разрешает подключать сторонние программы по API-ключу.',
  'terms.p6': 'Доступ. Данные видят только сотрудники Клиники по своим ролям: врач не видит финансовые данные пациентов. Действия сотрудников записываются в историю.',
  'terms.p7': 'Защита. Соединение защищено, ключ Cliniccards хранится зашифрованным, вход защищён паролем от 10 символов, ограничением попыток и подтверждением почты.',
  'terms.p8': 'Удаление. Клиника может в любой момент выгрузить свои данные и полностью удалить их из Сервиса в настройках. Из рабочей базы они исчезают сразу, в резервных копиях хранятся до их плановой замены.',
  'terms.p9': 'Инциденты. Если мы обнаружим утечку данных, сообщим Клинике без неоправданной задержки.',
  'terms.p10': "Мессенджеры. Для связи с пациентами Сервис пользуется Telegram (бот Клиники): это подрядчик, через которого проходят сообщения. Сервис пишет только тем, кто сам подключился к боту. Служебные сообщения (напоминания о записи) отправляются по настройкам Клиники, рекламные только пациентам, давшим согласие, и только с подтверждением сотрудника, если Клиника не решила иначе. Пациент может отказаться командой «Зупинити». Клиника отвечает за то, что вправе писать своим пациентам.",
  'terms.p11': "Искусственный интеллект. Помощник на основе ИИ выключен, пока Клиника его не включит. Если включён, текст сообщений пациента в чате с ботом и итоговые сведения из базы Клиники (например, сколько месяцев прошло с последней чистки, свободные окна расписания) передаются внешнему поставщику ИИ только для подготовки ответа. Имена и телефоны пациентов в запросах не передаются, но пациент может сам написать их в сообщении. ИИ не даёт медицинских советов: темы здоровья, цен и жалоб передаются сотруднику. Клиника может выключить помощника в любой момент. Поставщик ИИ является подрядчиком Сервиса. То же касается ИИ-помощника руководителя, если Клиника его включает: текст вопросов сотрудников к данным и итоговые числа отчётов без имён и телефонов пациентов передаются поставщику ИИ.",
  'terms.p12': "Изменения. Если смысл соглашения изменится, мы попросим владельца принять новую версию.",
