  'public.terms': "Terms of service",
  'public.privacy': "Privacy policy",
  'landing.login': "Sign in",
  'privacy.date': "Version of 30 October 2026",
  'privacy.contact': "Contact for data questions",
  'privacy.who.h': "Who we are",
  'privacy.who.t': "LANKA is a service for dental clinics. The clinic that uses it is the controller of its patients’ personal data; LANKA processes it on the clinic’s instruction and only to run the service.",
  'privacy.what.h': "What data is processed",
  'privacy.what.t': "Data about patients, appointments and treatment that the clinic takes from its own system (Cliniccards); staff data (name, email, role, action log); patients’ conversations with the clinic in the connected channels (Telegram, Instagram, Facebook Messenger, WhatsApp, Viber, the website chat) and the technical identifiers that go with them. Diagnoses, medical records and patient files are not read.",
  'privacy.why.h': "Why",
  'privacy.why.t': "Reports for the manager, reminders and replies to patients on behalf of the clinic, booking requests, statistics of inquiries. We do not sell data, use it for advertising or train models on it.",
  'privacy.who2.h': "Who receives the data",
  'privacy.who2.t': "Only the providers without which the service cannot work: hosting, email, a payment service, the messengers in which the clinic talks to patients, and an AI provider (only if the clinic turns AI on; patient names and phones are not sent to it). Each clinic’s data is separated from the others’.",
  'privacy.meta.h': "Facebook, Instagram, Messenger and WhatsApp",
  'privacy.meta.t': "The clinic connects its own account and grants access itself. We receive only the messages addressed to the clinic and reply within the platform rules (within 24 hours of the person’s message). Access tokens are stored encrypted. If you remove access in Facebook or Instagram, the connection and the tokens are deleted automatically.",
  'privacy.store.h': "Storage",
  'privacy.store.t': "Data is kept while the contract with the clinic is in force, in a protected database separated by clinic. After the contract ends it is deleted at the clinic’s request.",
  'privacy.rights.h': "Your rights",
  'privacy.rights.t': "A patient applies to the clinic, which is the controller of their data: it corrects or deletes it in its own system and LANKA is updated from there. Messages can be stopped at any time with the command “Stop”.",
  'privacy.delete.h': "Data deletion",
  'privacy.delete.t': "A data deletion request passed through Facebook or Instagram is handled automatically: the connected accounts with their tokens, the conversations and the chat links carrying your identifier are deleted. You receive a confirmation code and a page that shows the result.",
  'deletion.title': "Data deletion",
  'deletion.intro': "This page shows the result of a data deletion request made through Facebook or Instagram.",
  'deletion.notFound': "No request with this code was found.",
  'deletion.noCode': "No confirmation code was given.",
