  'dash.notLoaded1': 'The key is saved but data is not loaded yet. ',
  'terms.title': 'Personal data processing agreement',
  'terms.gateIntro': 'To keep working, accept the agreement on behalf of the clinic. The owner accepts it.',
  'terms.acceptReg': 'I accept the personal data processing agreement on behalf of the clinic.',
  'terms.readLink': 'Read the agreement',
  'terms.accept': 'I accept this agreement on behalf of the clinic',
  'terms.acceptBtn': 'Accept',
  'terms.p1': 'Parties. You act on behalf of the clinic (“Clinic”) and accept this agreement with LANKA (“Service”). You confirm you are authorised to do so.',
  'terms.p2': 'Roles. The Clinic remains the controller of its patients’ personal data. The Service processes it only on the Clinic’s instructions.',
  'terms.p3': "What the Service does. Using the Clinic’s API key it reads the Clinic’s data from Cliniccards (read-only: the Service changes and deletes nothing in Cliniccards), stores it and shows it to the Clinic’s staff in reports and task lists. If the Clinic turns it on, the Service also sends patients messages in messengers on the Clinic’s behalf (see items 10 and 11).",
  'terms.p4': "Purpose. Reports and tasks for the Clinic’s administrators and, if the Clinic turns it on, messages to patients and chat replies. The Service does not sell data or use it for advertising. Data goes to external AI services only as described in item 11.",
  'terms.p5': 'Basis. The Clinic confirms it is entitled to process this data, that patients signed its standard consent to personal data processing, and that Cliniccards allows third-party programs to connect with an API key.',
  'terms.p6': 'Access. Data is visible only to the Clinic’s staff according to their roles: doctors do not see patients’ financial data. Staff actions are logged.',
  'terms.p7': 'Protection. Connections are encrypted, the Cliniccards key is stored encrypted, sign-in is protected by a 10+ character password, attempt limits and email confirmation.',
  'terms.p8': 'Deletion. The Clinic can export its data and delete it from the Service completely at any time in settings. It disappears from the working database at once and stays in backups until they are rotated.',
  'terms.p9': 'Incidents. If we discover a data breach, we will inform the Clinic without undue delay.',
  'terms.p10': "Messengers. To contact patients the Service uses Telegram (the Clinic’s bot): a subcontractor through which messages pass. The Service writes only to people who connected to the bot themselves. Service messages (appointment reminders) are sent according to the Clinic’s settings; promotional ones only to patients who gave consent and only with staff approval unless the Clinic decides otherwise. A patient can opt out with the “Зупинити” command. The Clinic is responsible for being entitled to write to its patients.",
  'terms.p11': "Artificial intelligence. The AI assistant is off until the Clinic turns it on. When on, the text of a patient’s messages in the bot chat and summary facts from the Clinic’s database (for example, how many months have passed since the last cleaning, free schedule slots) are passed to an external AI provider only to prepare a reply. Patients’ names and phone numbers are not sent in requests, but a patient may write them in a message themselves. The AI gives no medical advice: health, price and complaint topics go to staff. The Clinic can turn the assistant off at any time. The AI provider is a subcontractor of the Service. The same applies to the manager AI assistant if the Clinic turns it on: the text of staff questions about the data and report totals without patients’ names and phone numbers are passed to the AI provider.",
  'terms.p12': "Changes. If the meaning of the agreement changes, we will ask the owner to accept the new version.",
  'auth.forgotLink': 'Forgot password?',
  'auth.forgotTitle': 'Reset password',
