const DICTS: Record<Locale, Record<Key, Entry>> = { uk, ru, en };
const INTL: Record<Locale, string> = { uk: 'uk-UA', ru: 'ru-RU', en: 'en-GB' };

// Текущий язык вне React: нужен клиенту API (заголовок Accept-Language) и форматам дат.
let current: Locale = DEFAULT_LOCALE;
export const getLocale = () => current;
export const intlLocale = () => INTL[current];

export function readStoredLocale(): Locale {
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    if (v === 'uk' || v === 'ru' || v === 'en') return v;
  } catch {
    /* localStorage недоступен: остаёмся на языке по умолчанию */
  }
  return DEFAULT_LOCALE;
}

function fill(text: string, params?: Record<string, string | number>) {
  return params ? text.replace(/\{(\w+)\}/g, (_, k) => String(params[k] ?? `{${k}}`)) : text;
}

// Перевод вне React-компонентов (например, в клиенте API); язык берётся из сохранённого выбора
export function translate(key: Key, params?: Record<string, string | number>): string {
  const v = DICTS[readStoredLocale()][key] ?? uk[key];
  return fill(Array.isArray(v) ? v.join(', ') : (v as string), params);
}

interface Ctx {
  locale: Locale;
  setLocale: (l: Locale) => void;
  t: (key: Key, params?: Record<string, string | number>) => string;
  tl: (key: Key) => string[];
  // Подпись по коду с запасным вариантом, если кода нет в словаре (например, новый статус Cliniccards)
  label: (prefix: LabelPrefix, code: string) => string;
}

export type LabelPrefix = 'status' | 'result' | 'role' | 'kind' | 'consent' | 'channel' | 'src' | 'audit' | 'imp.type';

const I18nContext = createContext<Ctx | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  // Первый рендер всегда на языке по умолчанию, чтобы сервер и клиент совпадали; сохранённый язык применяется в эффекте
  const [locale, setLocaleState] = useState<Locale>(DEFAULT_LOCALE);

  useEffect(() => {
    const stored = readStoredLocale();
    current = stored;
    setLocaleState(stored);
  }, []);

  useEffect(() => {
    current = locale;
    document.documentElement.lang = locale;
  }, [locale]);

  const setLocale = useCallback((l: Locale) => {
    current = l;
    try {
      localStorage.setItem(STORAGE_KEY, l);
    } catch {
      /* без сохранения язык действует до закрытия вкладки */
    }
    setLocaleState(l);
  }, []);

  const value = useMemo<Ctx>(() => {
    const dict = DICTS[locale];
    const t = (key: Key, params?: Record<string, string | number>) => {
      const v = dict[key] ?? uk[key];
      return fill(Array.isArray(v) ? v.join(', ') : (v as string), params);
    };
    const tl = (key: Key) => {
      const v = dict[key] ?? uk[key];
      return Array.isArray(v) ? (v as string[]) : [v as string];
    };
    const label = (prefix: LabelPrefix, code: string) => {
      const key = `${prefix}.${code}` as Key;
      return key in uk ? t(key) : code;
    };
    return { locale, setLocale, t, tl, label };
  }, [locale, setLocale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): Ctx {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('I18nProvider отсутствует');
  return ctx;
}

export const useT = () => useI18n().t;
